python - <<'PY'
import json,collections,subprocess
m=json.load(open('/tmp/candidate.json'))['diagrams'][0]['mappings']; files=list(dict.fromkeys(x['path'] for x in m));
for f in files:
 ranges=sorted(set((x['startLine'],x['endLine']) for x in m if x['path']==f)); spans=[]
 for b,e in ranges:
  if spans and b<=spans[-1][1]+1: spans[-1]=(spans[-1][0],max(e,spans[-1][1]))
  else: spans.append((b,e))
 with open('/tmp/read-selected-ranges','a') as o:
  o.write('\n==== '+f+'\n');
  for b,e in spans: o.write(subprocess.check_output(['bash','-c',f"nl -ba {f} | sed -n '{b},{e}p'"]).decode())
print('read selected ranges individually with file-relative nl -ba; lines:',sum(1 for _ in open('/tmp/read-selected-ranges')))
PY
sed -n '/==== src\/renderer\/generic.zig/,/==== src\/renderer\/State.zig/p' /tmp/read-selected-ranges | tail -125

